  Let BND : 4096 <= TH /\ TH + 4096 <= aceil /\ 6811648 <= CTX /\ CTX + 160 <= aceil
            /\ 0x10007fff8000 <= sb /\ sb + 137438953472 + 4096 <= aceil /\ 6811648 <= a_pa s /\ a_pa s + 8388608 <= aceil
            /\ 6811664 <= U /\ U + round_up size 8 <= aceil /\ 1 <= size /\ size <= round_up size 8 /\ round_up size 8 = 8 * nsh size
            /\ 2148302336 <= sh U /\ sh U + nsh size <= 0x10007fff8000 /\ U mod 16 = 0 /\ (sh U + nsh size <= U - 16 \/ U + round_up size 8 <= sh U) /\ (U + round_up size 8 <= 2147446784 \/ 17594333495296 <= U - 16) /\ (ch_end ch <= 2147446784 \/ 17594333495296 <= ch_lo ch).
  Proof.
    pose proof PURE as (Z1 & Z2 & Z3 & Z4 & Z5 & Z6 & Y1 & Y2 & Y3 & Y4 & Y5 & Y6 & X1 & X2 & X3 & _).
    pose proof PL as (_ & _ & _ & P1 & P2 & P3 & _). apply aapp_env in P2; [| unfold kPtrArrayReserve; clear; lia].
    pose proof (record_band s OK ch CHIN) as RBB. unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AIMG_TOP, AHI_LO in RBB.   (* [comment removed for export] *)
